{"file_path":"/tmp/.cat/claude/changelog-language-captures/php-code-claude-cat.rZ6aC9/claude/mss82s7b-zgsaf2z3z/project/tests/CheckoutPriceCalculatorTest.php","content":"<?php

declare(strict_types=1);

$autoload = dirname(__DIR__) . '/vendor/autoload.php';
if (is_file($autoload)) {
    require $autoload;
}
require dirname(__DIR__) . '/CheckoutPriceCalculator.php';

function assertSameValue(string $expected, string $actual, string $scenario): void
{
    if ($actual !== $expected) {
        throw new RuntimeException(sprintf(
            '%s: expected %s, got %s',
            $scenario,
            var_export($expected, true),
            var_export($actual, true)
        ));
    }
}

function assertInvalidArgument(callable $operation, string $expectedMessage, string $scenario): void
{
    try {
        $operation();
    } catch (InvalidArgumentException $exception) {
        assertSameValue($expectedMessage, $exception->getMessage(), $scenario);
        return;
    }

    throw new RuntimeException($scenario . ': expected InvalidArgumentException');
}

$calculator = new CheckoutPriceCalculator();

assertSameValue(
    '108.00',
    $calculator->calculate('100', '0.1', '0.2', ShippingMethod::Standard),
    'standard shipping applies discount before tax'
);
assertSameValue(
    '126.00',
    $calculator->calculate('100', '0.1', '0.2', ShippingMethod::Expedited),
    'expedited shipping is added after discount and before tax'
);
assertSameValue(
    '0.01',
    $calculator->calculate('0.01', '0.1', '0.1', ShippingMethod::Standard),
    'intermediate results are not rounded'
);
assertSameValue(
    '1.00',
    $calculator->calculate('1.005', '0', '0', ShippingMethod::Standard),
    'half-even rounds a tie toward an even lower cent'
);
assertSameValue(
    '1.02',
    $calculator->calculate('1.015', '0', '0', ShippingMethod::Standard),
    'half-even rounds a tie toward an even upper cent'
);
assertSameValue(
    '1000000000000000000000000000000000000.00',
    $calculator->calculate(
        '999999999999999999999999999999999999.995',
        '0',
        '0',
        ShippingMethod::Standard
    ),
    'arbitrarily large accepted prices remain exact'
);
assertSameValue(
    '0.00',
    $calculator->calculate('123.456', '1', '1', ShippingMethod::Standard),
    'inclusive rate boundaries are accepted'
);
assertSameValue(
    '0.01',
    $calculator->calculate('00.0100', '0.00', '0.000', ShippingMethod::Standard),
    'leading and trailing zeroes are accepted'
);

foreach (['', '.1', '1.', '-1', '+1', '1e2', ' 1', '1,000'] as $invalidPrice) {
    assertInvalidArgument(
        fn (): string => $calculator->calculate(
            $invalidPrice,
            '0',
            '0',
            ShippingMethod::Standard
        ),
        'Item price must be a nonnegative decimal string in plain notation.',
        'invalid item price ' . var_export($invalidPrice, true)
    );
}

foreach (['', '.1', '1.', '-0.1', '1.01', '2', '1e-1', ' 0.1'] as $invalidRate) {
    assertInvalidArgument(
        fn (): string => $calculator->calculate(
            '1',
            $invalidRate,
            '0',
            ShippingMethod::Standard
        ),
        'Discount rate must be a decimal string in the inclusive range [0, 1].',
        'invalid discount rate ' . var_export($invalidRate, true)
    );
    assertInvalidArgument(
        fn (): string => $calculator->calculate(
            '1',
            '0',
            $invalidRate,
            ShippingMethod::Standard
        ),
        'Tax rate must be a decimal string in the inclusive range [0, 1].',
        'invalid tax rate ' . var_export($invalidRate, true)
    );
}

fwrite(STDOUT, "CheckoutPriceCalculator tests passed.\n");
"}

{"file_path":"/tmp/.cat/claude/changelog-language-captures/php-code-claude-cat.rZ6aC9/claude/mss82s7b-zgsaf2z3z/project/CheckoutPriceCalculator.php","content":"<?php

declare(strict_types=1);

use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;

enum ShippingMethod
{
    case Standard;
    case Expedited;
}

final class CheckoutPriceCalculator
{
    private const string EXPEDITED_SHIPPING_FEE = '15.00';
    private const string DECIMAL_PATTERN = '/\A\d+(?:\.\d+)?\z/D';

    /**
     * Calculates the exact checkout total for one item in the currency unit used by the item price.
     *
     * The discount applies only to the item price. Expedited shipping is then added, tax is applied,
     * and the result is rounded once to two decimal places using half-even rounding.
     *
     * @throws InvalidArgumentException if an amount or rate does not satisfy its documented format or range
     */
    public function calculate(
        string $itemPrice,
        string $discountRate,
        string $taxRate,
        ShippingMethod $shippingMethod
    ): string {
        $price = $this->parseNonnegativeDecimal(
            $itemPrice,
            'Item price must be a nonnegative decimal string in plain notation.'
        );
        $discount = $this->parseRate(
            $discountRate,
            'Discount rate must be a decimal string in the inclusive range [0, 1].'
        );
        $tax = $this->parseRate(
            $taxRate,
            'Tax rate must be a decimal string in the inclusive range [0, 1].'
        );

        $discountedPrice = $price->multipliedBy(BigDecimal::one()->minus($discount));
        $shippingFee = $shippingMethod === ShippingMethod::Expedited
            ? BigDecimal::of(self::EXPEDITED_SHIPPING_FEE)
            : BigDecimal::zero();
        $taxableSubtotal = $discountedPrice->plus($shippingFee);
        $total = $taxableSubtotal->multipliedBy(BigDecimal::one()->plus($tax));

        return (string) $total->toScale(2, RoundingMode::HalfEven);
    }

    private function parseNonnegativeDecimal(string $value, string $failureMessage): BigDecimal
    {
        if (preg_match(self::DECIMAL_PATTERN, $value) !== 1) {
            throw new InvalidArgumentException($failureMessage);
        }

        return BigDecimal::of($value);
    }

    private function parseRate(string $value, string $failureMessage): BigDecimal
    {
        $rate = $this->parseNonnegativeDecimal($value, $failureMessage);
        if ($rate->isGreaterThan(BigDecimal::one())) {
            throw new InvalidArgumentException($failureMessage);
        }

        return $rate;
    }
}
"}

